// src/lab/sdf-zombie/webgpu/explosion-vfx.ts
//
// PROCEDURAL GPU explosion burst — the visual half of `resolveExplosion`'s
// `BurstVisual` (../explosion-aoe.ts). No image assets, no atlas, no flipbook:
// every pixel of fire, smoke, ember and shockwave is generated by TSL node
// graphs evaluated on the GPU, advected by a `time` uniform and remapped
// through a blackbody-ish ramp.
//
// ── BILLBOARD BUDGET (the number a caller needs) ────────────────────────
//   fire  14   additive, staggered bloom-then-stretch billboards
//   smoke  8   normal-blended, late-blooming rising billboards
//   ember 12   additive ballistic streaks, CPU-stepped, pooled
//   ring   1   additive expanding shockwave annulus
//   ─────────
//   35 per burst at the default tuning (the brief's "well under ~40").
// Hard caps are 20 + 12 + 18 + 1 = 51 per burst and at most
// EXPLOSION_VFX_LIMITS.maxBursts (6) bursts are ever live, so the module can
// never draw more than 306 billboards.
//
// DRAW CALLS: 4 total, not 4-per-burst. Each layer is ONE dynamic
// BufferGeometry the CPU refills each frame (vertices baked in WORLD space,
// geometry at the origin, frustumCulled off) and ONE node material — 1 fire
// + 1 smoke + 1 ember + 1 ring. A fifth live burst costs zero extra draw
// calls. The CPU half is deliberate: camera basis, roll and envelope stay in
// testable pure code, while every *look* decision — noise, ramp, falloff —
// stays in the node graph.
//
// ── THE TRANSPARENCY TRAP, AND WHAT THIS FILE DOES ABOUT IT ─────────────
// kit-overlay.ts:78-90 writes up the failure: the SDF layer composites its
// flesh as a fullscreen quad that DEPTH-TESTS against the polygon depth
// buffer, so translucent geometry drawn in the polygon pass is either erased
// by the flesh (depthWrite off) or punches a hole showing the background
// (depthWrite on). character-effects.ts:6-8 records the repo's fix, and this
// module is designed to be another tenant of it: the caller adds `vfx.object`
// to the SEPARATE effects scene that game-main renders AFTER the composite
// with `renderer.autoClear = false`. In that position `transparent: true`
// composes correctly against the finished frame, and `depthTest: true` still
// lets walls and bodies occlude a burst.
//
// Concretely, for the two WebGPU-specific landmines this repo has hit:
//   * `alphaHash` is NOT used anywhere in this file. blood-view-gpu.ts:154
//     records that hashed coverage rendered the quads as unshaped translucent
//     SQUARES on the WebGPU backend (the map's alpha never gated coverage).
//     createExplosionLookMaterial keeps the path reachable behind
//     `alphaControl: 'hash'` purely so the spike page can re-photograph the
//     failure next to the working one.
//   * `alphaTest` is NOT used either. blood-view-gpu notes a cutout is what
//     makes its droplet path survive the composite, but a cutout has no soft
//     glow, and a fireball is entirely glow. Coverage comes from the node
//     graph's alpha instead — `colorNode.w`, which NodeMaterial assigns
//     straight to `diffuseColor.a` (NodeMaterial.js:856-862) — plus the blend
//     factors, which were read out of this build rather than assumed:
//       AdditiveBlending, premultipliedAlpha:false -> (SrcAlpha, One)
//       NormalBlending,   premultipliedAlpha:false -> (SrcAlpha, OneMinusSrcAlpha)
//     (WebGPUPipelineUtils.js:560-575.) So `colorNode = vec4(rgb, coverage)`
//     adds rgb*coverage for fire and lerps rgb by coverage for smoke — the
//     standard non-premultiplied behaviour on this backend.
//
// ── DETERMINISM ─────────────────────────────────────────────────────────
// No Math.random() anywhere, per-frame or at spawn. All per-billboard
// randomness is drawn ONCE at spawn() from a seeded mulberry32 (imported from
// game-weapon.ts, the repo's canonical copy) and stored in preallocated
// Float32Arrays; update() only reads it. spawn(visual, seed) pins the seed for
// a capture; a driver that pins the seed sequence AND the dt sequence gets a
// reproducible frame.
//
// EVERYTHING IS PREALLOCATED at construction: geometries, attributes,
// materials, uniforms and all per-slot parameter storage. spawn() and
// update() allocate nothing.
//
// ROUTING NOTE: vertices are world-space, so `object` must be added to a
// scene whose root transform is the identity (characterEffects.scene is).

import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  attribute, clamp, float, length, linearDepth, min, mix, mx_fractal_noise_float,
  positionWorld, smoothstep, uniform, vec2, vec3, vec4,
} from 'three/tsl';
import { mulberry32 } from './game-weapon';
import { curlVector } from './curl-volume-node';
import { softParticleFade } from './soft-fade';
import type { Vec3 } from '../types';
import type { BurstVisual } from '../explosion-aoe';

// ————————————————————————————————————————————————————————————————————————
// Public types (the interface other code is written against)
// ————————————————————————————————————————————————————————————————————————

export interface ExplosionVfxTuning {
  /** Overall additive fire brightness multiplier. */ gain: number;
  /** Fireball half-height in metres for a 1.0-scale burst, times BurstVisual.heightM. */
  fireScale: number;
  /** Seconds the whole burst lasts. */ lifeSec: number;
  /** Number of fire billboards per burst. */ fireCount: number;
  /** Number of smoke billboards per burst. */ smokeCount: number;
  /** Number of ballistic embers per burst. */ emberCount: number;
  /** Shockwave ring speed (m/s) and its fade. */ ringSpeedMps: number;
  /** Peak dynamic-light intensity fed back to the caller (0 disables). */
  lightIntensity: number;
  /** Base seed for the per-burst LCG when spawn() gets no pinned seed. */
  seed: number;
  /** SMOKE opacity multiplier. 0 kills the normal-blended layer entirely
   *  (the smoke A/B); 1 is the authored density. */
  smokeOpacity: number;
  /** SHOCKWAVE ring alpha multiplier. 0 disables the ring. */
  ringOpacity: number;
  /**
   * THE PLUME'S TWO HEIGHTS, in half-heights above the burst's centre: where
   * the fire NECK tops out and where the smoke CAP does. These are what make a
   * mushroom instead of a ball — the neck's clamp is what stops the fire
   * growing into a sphere, and the gap between the two is the stem.
   *
   * They are the HEIGHT at the end of the layer's life, not a clamp on a
   * curve, so the silhouette is stated here rather than deduced from one.
   */
  plumeNeckH: number;
  plumeCapH: number;
  /**
   * How flat the smoke cap draws at the end of its life, as a fraction of the
   * cap's own horizontal size. 1 is a sphere; the owner's reference is a
   * mushroom, so the cap ends up WIDER THAN TALL — the one place this effect
   * is allowed to un-stretch, and the reason `stretchY` alone could never
   * produce the shape (it is >= 1 everywhere, i.e. everything is taller than
   * it is wide).
   */
  capFlatten: number;
  /**
   * EMBER speed in half-heights per second. Was absolute m/s (3.5-14.5, i.e.
   * sparks crossing ~4 m — about 11 half-heights — while the plume they came
   * out of is 2). Sparks that outrun their own explosion by 10x read as a
   * separate effect, so this now scales with the burst like everything else.
   */
  emberSpeedPerH: number;
  /**
   * How far the ground shockwave front may travel, in half-heights. The ring's
   * speed is a real m/s (9 by default) and its life is short, but nothing tied
   * its REACH to the burst: at the shipped size the front ran 4.2 m out of a
   * 0.84 m plume — twelve times the fireball it came from, a swept ring on the
   * far side of the room. Clamped so the front reads as the plume's own
   * pressure wave, still decelerating, still fading.
   */
  ringReachH: number;
  /**
   * THE PLUME A/B, 0..1. 1 is the mushroom; 0 is the round fireball this
   * effect used to be. It blends the three terms that ARE the shape — the
   * neck's convergence, the cap's outward roll, and the cap's flattening —
   * back to the constant 1.0 they were, and it blends the smoke's spawn
   * azimuth from the rim back to a uniform-in-the-ball draw.
   *
   * It exists because "is it a mushroom yet" is the owner's call and the only
   * honest way to make it is a switch between the two, in one boot, on the
   * same burst. The spawn DISTRIBUTION is deliberately included: shape here is
   * not only the envelopes — a uniform draw in the unit ball puts most
   * billboards near the centre whatever the envelopes do.
   */
  plumeMix: number;
  /**
   * Share of the FIRE billboards that take the CAP envelope instead of the
   * neck's, 0..1. 0 is fire-as-column-only (the bottom-heavy read the atlas
   * measurement rejects); 1 is every fire billboard riding the cap, which
   * leaves no column at all.
   */
  fireCapShare: number;
  /**
   * The CAP fire's flatness at the end of its life, 0..1 — the neck never
   * flattens; this is what stops the top of the plume being a sphere.
   */
  capFireFlatten: number;
  /**
   * CURL MOTION (explosion-curl task). How hard the SHARED divergence-free
   * curl volume (curl-volume-node.ts) domain-warps the fire and smoke noise
   * lookup, in noise-domain units. 0 is the game's default and contributes
   * EXACTLY zero — the pre-curl scrolling look, unchanged — so the new swirl
   * is opt-in; the spike page turns it on and the owner decides whether to
   * lift the game default. Bounds [0, 2]. The applied amplitude is budgeted by
   * `curlWarpGain` so that a tight `curlScale` cannot compress the lookup (the
   * straight-cross defect); at the shipped `curlScale` (18 m) the full value is
   * applied.
   */
  curlStrength: number;
  /**
   * World metres per curl-volume repeat: the shader samples the field at
   * `fragmentWorld / curlScale`. Smaller is more, tighter swirl cells (a
   * fireball is a few metres across, so ~2.5 reads as a rolling ball where the
   * flame cards' ~6 m body scale would be one cell). Only meaningful when
   * `curlStrength > 0`.
   *
   * IT ALSO SETS THE COMPRESSION BUDGET: the warp's spatial gradient grows as
   * `curlStrength / curlScale`, and once it compresses the noise lookup a
   * single fire billboard shows a straight cross. The measured clean bound is
   * `strength / curlScale <= CURL_WARP_SAFE_RATIO` (0.06), so the shipped 1.1
   * needs **18 m** — at 6 m the full strength still crossed (see the 2026-09-18
   * NOTES, second pass). Below that scale the applied amplitude is scaled down
   * with `curlScale` (`curlWarpGain`). Ship at 18.
   */
  curlScale: number;
  /**
   * SOFT-PARTICLE FADE distance in metres (soft-fade.ts): translucent fire and
   * smoke fade out as they approach the scene surface behind them, so the hard
   * straight cut where a quad meets the floor or a wall becomes a gradient.
   * 0 is the game's default and is fully inert (the identical frame). Bounds
   * [0, 2] metres.
   */
  softFade: number;
}

export const EXPLOSION_VFX_TUNING: ExplosionVfxTuning = {
  gain: 1.35,
  fireScale: 1.0,
  lifeSec: 1.5,
  fireCount: 14,
  smokeCount: 8,
  emberCount: 12,
  ringSpeedMps: 9,
  lightIntensity: 5,
  seed: 0x5eed1234,
  smokeOpacity: 1,
  ringOpacity: 1,
  // 2.0 and 2.6 half-heights: at the shipped size (halfH 0.84 m) that is a
  // 1.7 m neck under a cap topping out at 2.2 m, against the atlas reference's
  // 1.65 m quad. The numbers are in HALF-HEIGHTS, so ?fxsize zooms the whole
  // silhouette without changing its proportions.
  plumeNeckH: 1.35,
  plumeCapH: 2.0,
  capFlatten: 0.55,
  emberSpeedPerH: 4.5,
  // 1.4, not 2.4: measured on the differential capture, a 2.4-half-height
  // ground ring put 75k of the burst's 93k changed pixels in a flat band across
  // the bottom of the frame — the ring WAS the explosion as far as the frame
  // was concerned, and it is what made the burst read wide and low whatever the
  // plume above it did. The reference's ground burst has a small base.
  ringReachH: 1.4,
  plumeMix: 1,
  fireCapShare: 0.5,
  capFireFlatten: 0.5,
  // BOTH NEW SWITCHES SHIP OFF: the game's explosions are the pre-curl look
  // until the owner flips these (one line each). See the interface above.
  // curlScale already carries the ship value (18, the compression-safe scale
  // for curlStrength 1.1) so a one-line strength flip cannot reintroduce the
  // cross; at curlStrength 0 it multiplies nothing.
  curlStrength: 0,
  curlScale: 18,
  softFade: 0,
};

export interface ExplosionVfx {
  /** Add THIS to the effects overlay scene (see routing in the file header). */
  readonly object: THREE.Object3D;
  /**
   * Spawn one burst at visual.at. Safe to call several times per second.
   *
   * `seed` is OPTIONAL and purely additive to the required signature: the
   * ordinary call is `spawn(visual)`, which draws its seed from the tuning
   * base plus a spawn counter. A capture driver that wants a reproducible
   * burst passes a pinned seed, which makes that burst independent of how many
   * bursts came before it.
   */
  spawn(visual: BurstVisual, seed?: number): void;
  /** Advance simulation/animation. `camera` is used for billboard facing. */
  update(dtSec: number, camera: THREE.Camera): void;
  /** The current peak light intensity this frame, for the caller to feed the
   *  dynamic light list. 0 when no burst is alive. */
  readonly lightIntensity: number;
  /** Live tuning seam (a test page / panel drives this). */
  setTuning(t: Partial<ExplosionVfxTuning>): void;
  readonly tuning: ExplosionVfxTuning;
  /** Desktop-only quick switch between fire looks, for the owner's A/B. */
  readonly activeBursts: number;
  /**
   * THE BURST'S OWN SHAPE, IN METRES — what the effect actually emitted this
   * frame, per layer: how many quads, the world-space box they cover, and how
   * their mass is distributed vertically (the mean height and the quartile
   * split).
   *
   * WHY AT THE SOURCE. The only other way to ask "is it a mushroom" is to
   * photograph the burst and read the changed pixels, and that instrument is
   * confounded twice over: the ground RING is a large low-lying annulus that
   * dominates the changed area (so a whole-burst mass centroid is mostly the
   * ring's height), and the changed region's BOUNDING BOX is re-cut by a single
   * stray pixel (so any band split by height reorders between boots). This is
   * deterministic, per layer, in world units, and it needs no GPU readback.
   */
  readonly layerExtents: Record<'fire' | 'smoke' | 'ember' | 'ring', LayerExtent>;
  /** The half-height this frame's bursts were laid out against, in metres —
   *  the number every extent above should be read RELATIVE to. */
  readonly burstHalfHeightM: number;
  dispose(): void;
}

/** One layer's emitted shape this frame, in world metres. */
export interface LayerExtent {
  /** Quads written (0 when the layer drew nothing). */
  count: number;
  /** World box of the quad CENTRES — not their billboard corners: a quad's own
   *  size is the billboard, and mixing the two makes a wide quad's box look
   *  like a wide cloud. */
  min: [number, number, number];
  max: [number, number, number];
  /** Mean centre height, and the mean height of the bottom and top quartiles —
   *  the shape question ("is the mass up top") as three numbers. */
  meanY: number;
  lowQuartileY: number;
  highQuartileY: number;
}

