  maxBursts: 6,
  maxFirePerBurst: 20,
  maxSmokePerBurst: 12,
  maxEmberPerBurst: 18,
  /** Billboards one default burst draws: 14 fire + 8 smoke + 12 embers + 1 ring. */
  billboardsPerDefaultBurst: 35,
